select slug, (select count(*) from regexp_matches(regexp_replace(content_fr, 'rendez-vous', '', 'gi'), '\m(vous|votre|vos)\M', 'gi')) as vous_brut, (select count(*) from regexp_matches(regexp_replace(regexp_replace(content_fr, '\]\([^)]*\)', ']', 'g'), 'rendez-vous', '', 'gi'), '\m(vous|votre|vos)\M', 'gi')) as vous_hors_url from blog_posts where slug in ('coliving-geneve-frontaliers-guide-complet','teletravail-frontalier-geneve-regles-2026','permis-g-frontalier-geneve','banque-telephone-internet-frontalier-bons-plans','coliving-vs-colocation-differences','avenant-fiscal-40-frontalier-geneve','transport-annemasse-geneve-leman-express','cout-transport-frontalier-geneve-2026','colocation-annemasse-ville-la-grand-ambilly','declaration-impots-frontalier-2026','optimiser-espace-coliving-productivite-bien-etre','coliving-annemasse-geneve-frontaliers-avantages','vie-quotidienne-frontalier-courses-sport-sorties','grand-geneve-2026-nouveautes-frontaliers') order by slug;

-- Contrôle APRÈS des impératifs de vouvoiement restants (verbes en -ez, « rendez-vous » neutralisé) : attendu 0 ligne
select slug, m[1] as mot from blog_posts, regexp_matches(regexp_replace(content_fr, 'rendez-vous', '', 'gi'), '(?:^|[\s*>#-])((?:[A-ZÉ][a-zé]+|[a-zé]+)ez)\M', 'g') as m where slug in ('coliving-geneve-frontaliers-guide-complet','teletravail-frontalier-geneve-regles-2026','permis-g-frontalier-geneve','banque-telephone-internet-frontalier-bons-plans','coliving-vs-colocation-differences','avenant-fiscal-40-frontalier-geneve','transport-annemasse-geneve-leman-express','cout-transport-frontalier-geneve-2026','colocation-annemasse-ville-la-grand-ambilly','declaration-impots-frontalier-2026','optimiser-espace-coliving-productivite-bien-etre','coliving-annemasse-geneve-frontaliers-avantages','vie-quotidienne-frontalier-courses-sport-sorties','grand-geneve-2026-nouveautes-frontaliers') and lower(m[1]) not in ('chez','assez','rez','nez') order by 1, 2;
-- ---------------------------------------------------------------------------
-- Ajout validé par Jérôme le 03/09 (hors tutoiement, même article colocation-annemasse) :
--   retrait du paragraphe « **Roomlala** : … » (plateforme interdite par CLAUDE.md §4, concurrent nommé)
--   et coquille « numero fictif » → « numéro fictif ». Exécuté APRÈS l'UPDATE de l'article.
update blog_posts set content_fr = replace(regexp_replace(content_fr, '\n\n\*\*Roomlala\*\*[^\n]*', ''), 'numero fictif', 'numéro fictif'), updated_at = now() where slug = 'colocation-annemasse-ville-la-grand-ambilly';
